head.b:skin:
/* ============================================================
   Fonts, inlined.

   Both families are variable fonts, so one file per subset covers
   every weight this theme uses: Space Grotesk 400-700 (headings,
   nav, buttons) and Source Serif 4 400-600 (body). The browser
   downloads a subset only if a glyph in it is actually rendered,
   so an English page pulls the two "latin" files and nothing else.

   font-display:swap paints the fallback immediately and swaps the
   webfont in, which is what keeps FCP off the critical path.
   ============================================================ */
@font-face{
  font-family:'Source Serif 4';font-style:normal;font-weight:400 600;font-display:swap;
  src:url(https://fonts.gstatic.com/s/sourceserif4/v14/vEFI2_tTDB4M7-auWDN0ahZJW1gb8tc.woff2) format('woff2');
  unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;
}
@font-face{
  font-family:'Source Serif 4';font-style:normal;font-weight:400 600;font-display:swap;
  src:url(https://fonts.gstatic.com/s/sourceserif4/v14/vEFI2_tTDB4M7-auWDN0ahZJW1gV8tenXg.woff2) format('woff2');
  unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF;
}
@font-face{
  font-family:'Space Grotesk';font-style:normal;font-weight:400 700;font-display:swap;
  src:url(https://fonts.gstatic.com/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4Cw.woff2) format('woff2');
  unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;
}
@font-face{
  font-family:'Space Grotesk';font-style:normal;font-weight:400 700;font-display:swap;
  src:url(https://fonts.gstatic.com/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPb94C-s0.woff2) format('woff2');
  unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF;
}

/* Metric-adjusted fallbacks. font-display:swap means the page first paints in
   the fallback and then re-lays out in the webfont; without these two faces
   that swap moves every line of text (CLS). size-adjust scales the fallback to
   the webfont's average glyph width so the reflow is a couple of pixels, not a
   paragraph. */
@font-face{
  font-family:'Space Grotesk Fallback';src:local('Arial'),local('Helvetica');
  size-adjust:104%;ascent-override:90%;descent-override:22%;line-gap-override:0%;
}
@font-face{
  font-family:'Source Serif 4 Fallback';src:local('Georgia'),local('Times New Roman');
  size-adjust:101%;ascent-override:94%;descent-override:26%;line-gap-override:0%;
}

:root{
  --bg:#F7F8FA; --surface:#FFFFFF; --ink:#1B1F27; --ink-soft:#5B6270;
  --line:#E4E7EC; --accent:#1F6F5C; --accent-ink:#0F4A3C; --gold:#C77D2E;
  --max:1160px;
  --font-head:'Space Grotesk','Space Grotesk Fallback',system-ui,sans-serif;
  --font-body:'Source Serif 4','Source Serif 4 Fallback',Georgia,serif;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0;background:var(--bg);color:var(--ink);
  font-family:var(--font-body);font-size:17px;line-height:1.65}
a{color:inherit;text-decoration:none}
img{max-width:100%;height:auto;display:block}
.container{width:min(var(--max),calc(100% - 32px));margin:auto}

/* Keyboard: every interactive element gets a visible ring. Blogger's own
   outline:0 on the search field is overridden below. */
a:focus-visible,button:focus-visible,input:focus-visible,
summary:focus-visible,[tabindex]:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.nav a:focus-visible,.footer a:focus-visible{outline-color:#FFD98A}
.skip-link{position:absolute;left:8px;top:-100px;z-index:200;background:var(--accent);color:#fff;
  font-family:var(--font-head);font-size:14px;font-weight:600;padding:12px 18px;border-radius:0 0 6px 6px;
  transition:top .12s ease}
.skip-link:focus{top:0}

.header{background:var(--surface);border-bottom:1px solid var(--line)}
/* Brand in the LEFT corner of the bar, social icons in the RIGHT corner,
   always on the same line. This used to be a flex row with flex-wrap:wrap:
   the moment the title + tagline were wider than the space left beside them
   - any phone, or desktop with a long blog description - the icons wrapped
   onto a second line, and a wrapped line holds only one item, so
   justify-content:space-between left-aligned it. Result: the icons sat
   *under* "Free Stack Hub" instead of opposite it. A two-column grid has no
   wrap to fall back on, so the icons stay pinned to the right edge and the
   brand column absorbs the squeeze (minmax(0,1fr) + overflow-wrap). */
.brand-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;
  min-height:100px;padding:18px 0;column-gap:24px}
.brand{display:block;min-width:0}
.brand-title{font-family:var(--font-head);font-size:26px;font-weight:700;letter-spacing:-0.01em;
  line-height:1.2;overflow-wrap:break-word}
.brand-title span{color:var(--accent)}
.brand-tagline{font-size:12.5px;color:var(--ink-soft);margin-top:3px;overflow-wrap:break-word}
/* align-self:start overrides the grid's align-items:center, so the icons
   hug the TOP of the bar instead of sitting at its vertical middle. */
.social-row{display:flex;align-items:center;justify-content:flex-end;gap:6px;align-self:start}
/* A 34px round hit area around a 19px glyph: the bare icon was an 18px tap
   target, which is what the mobile Accessibility audit reports as "tap
   targets are not sized appropriately". */
.social-row a{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;
  border-radius:50%;color:var(--ink-soft);transition:background-color .16s ease,color .16s ease}
.social-row a:hover,.social-row a:focus-visible{color:var(--accent-ink);background:#E4F1ED}
.social-row svg{width:19px;height:19px}

.nav-wrap{background:var(--ink)}
.nav{min-height:46px;display:flex;align-items:center;gap:0;overflow-x:auto;white-space:nowrap}
.nav a{padding:13px 16px;font-family:var(--font-head);font-size:13.5px;font-weight:500;color:#EDEFF2;border-right:1px solid rgba(255,255,255,.08)}
.nav a:hover{background:var(--accent);color:#fff}

.search-wrap{padding:16px 0;border-bottom:1px solid var(--line);background:var(--surface)}
.search{display:flex;max-width:560px;margin:auto}
.search input{flex:1;min-width:0;border:1px solid var(--line);border-right:0;padding:11px 13px;
  font-family:var(--font-body);font-size:15px}
.search input:focus{outline:3px solid var(--accent);outline-offset:-3px}
.search input::placeholder{color:#4A5160;opacity:1}
.search button{border:1px solid var(--accent);background:var(--accent);color:#fff;padding:0 18px;cursor:pointer;font-family:var(--font-head);font-weight:600;font-size:13px}

.ad-slot{margin:20px 0}
.ad-slot .ad-inner{border:1px dashed var(--line);background:var(--surface);text-align:center;padding:12px}
.ad-slot .ad-label{font-family:var(--font-head);font-size:10px;letter-spacing:.08em;color:var(--ink-soft);text-transform:uppercase;margin-bottom:6px}

.main-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:34px;padding:28px 0}
.content-area{min-width:0}

.post-outer{background:var(--surface);border:1px solid var(--line);padding:22px 24px;margin:0 0 20px}
.post-title{font-family:var(--font-head);font-size:24px;line-height:1.3;margin:0 0 8px;font-weight:600}
.post-title a:hover{color:var(--accent)}
.post-meta,.post-timestamp{font-size:12.5px;color:var(--ink-soft)}
.post-header{border-bottom:1px solid var(--line);padding-bottom:12px;margin-bottom:14px}
.post-body{font-size:16.5px}
.post-body pre{background:#12161C;color:#E7E9EE;padding:13px;overflow:auto;font-size:13.5px}
.post-labels{margin-top:14px}
.post-labels a:hover{background:var(--accent);color:#fff}
.post-footer{margin-top:14px;padding-top:12px;border-top:1px solid var(--line);font-size:12.5px;color:var(--ink-soft)}

.download-box{margin:20px 0;padding:16px 18px;border:1px solid var(--accent);background:#F0F6F4}
.download-box strong{display:block;font-family:var(--font-head);font-size:15px;margin-bottom:4px}
.download-box .meta{font-size:13px;color:var(--ink-soft);margin-bottom:10px}
.download-box a.dl-btn{display:inline-block;background:var(--accent);color:#fff;font-family:var(--font-head);font-weight:600;font-size:13.5px;padding:9px 18px}
.download-box a.dl-btn:hover{background:var(--accent-ink)}

.sidebar{min-width:0}
.widget{background:var(--surface);border:1px solid var(--line);margin-bottom:20px}
.widget h2,.widget h3{font-family:var(--font-head);font-size:12.5px;letter-spacing:.05em;text-transform:uppercase;color:var(--ink-soft);margin:0;padding:13px 15px;border-bottom:1px solid var(--line)}
.widget-content{padding:12px 15px 15px}
.sidebar ul{list-style:none;margin:0;padding:0}
.sidebar li{border-bottom:1px solid var(--line);padding:8px 0;font-size:13.5px}
.sidebar li:last-child{border-bottom:none}
.sidebar a:hover{color:var(--accent)}

.footer{border-top:1px solid var(--line);background:var(--ink);color:#C7CBD3;padding:28px 0 18px;margin-top:10px}
.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:26px}
.footer h3{font-family:var(--font-head);font-size:13px;text-transform:uppercase;letter-spacing:.05em;color:#fff;margin-top:0}
.footer p,.footer li{font-size:13px;color:#B7BCC6}
.footer ul{list-style:none;padding:0;margin:0}
.footer li{padding:4px 0}
.footer a:hover{color:var(--gold)}
.copyright{border-top:1px solid rgba(255,255,255,.1);margin-top:20px;padding-top:14px;text-align:center;font-size:12px;color:#A8B0BE}

.blog-pager{display:flex;justify-content:center;gap:10px;margin:16px 0 6px}
.blog-pager a{border:1px solid var(--line);background:var(--surface);padding:8px 14px;font-family:var(--font-head);font-size:13px}
.blog-pager a:hover{border-color:var(--accent);color:var(--accent)}
.feed-links{display:none}
.post-share-buttons,.post-share-buttons-bottom,.share-buttons,.PostShare,.gs-c-share{display:none !important}

@media(max-width:860px){
  .main-layout{grid-template-columns:1fr;gap:14px}
  .footer-grid{grid-template-columns:1fr}
}
@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{transition-duration:.001ms !important;animation-duration:.001ms !important;
    animation-iteration-count:1 !important;scroll-behavior:auto !important}
}
@media(max-width:560px){
  /* Still one line, still two corners - just tighter, so the icons never
     crowd the wordmark. Nothing here re-wraps the header. */
  .brand-row{min-height:76px;padding:12px 0;column-gap:10px}
  .brand-title{font-size:20px}
  .brand-tagline{font-size:11.5px}
  .social-row{gap:0}
  .social-row a{width:31px;height:31px}
  .social-row svg{width:17px;height:17px}
  .post-title{font-size:20px}
  .post-outer{padding:18px}
}

/* ============================================================
   List cards (home / label / search / archive).
   Each card is the feature image full width across the top,
   then the labels, the title, the date and a Read More button
   that opens that post's own URL. Deliberately NO body text:
   the cards used to print data:post.snippets.long, which is
   roughly the first 1000 characters of the post, so the home
   page read like a wall of the post itself.
   ============================================================ */
.post-list{display:flex;flex-direction:column;gap:24px}
.post-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;overflow:hidden;
  transition:border-color .16s ease, box-shadow .16s ease}
.post-card:hover{border-color:#CFD6E0;box-shadow:0 12px 28px rgba(16,24,40,.08)}
/* The image gets a fixed 16:9 box, filled with object-fit:cover. The old
   side-column version stretched the image to the card's full height on wide
   screens (min-height:100% + height:100%), which cropped away most of it -
   that is why post images looked broken on PC. */
.card-media{display:block;background:#EAEEF3;aspect-ratio:16/9;overflow:hidden}
.card-media img{width:100%;height:100%;object-fit:cover}
/* Blogger renders Label thumbnails with markup this theme does not control;
   pinning a square box means they cannot push the column down. */
.sidebar .widget img{aspect-ratio:1/1;height:auto;object-fit:cover}
.card-body{padding:20px 22px;min-width:0;display:flex;flex-direction:column;align-items:flex-start}
.card-tags{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 10px}
.card-tags a{font-family:var(--font-head);font-size:10.5px;font-weight:600;letter-spacing:.07em;
  text-transform:uppercase;color:var(--accent);background:#EAF3F0;padding:4px 9px;border-radius:4px}
.card-tags a:hover{background:var(--accent);color:#fff}
.card-title{font-family:var(--font-head);font-size:22px;line-height:1.28;font-weight:600;margin:0 0 8px}
.card-title a:hover{color:var(--accent)}
.card-meta{font-size:12.5px;color:var(--ink-soft);margin:0 0 12px}
.card-more{margin-top:14px}
.read-more{display:inline-flex;align-items:center;gap:9px;background:var(--accent);color:#fff;
  font-family:var(--font-head);font-size:13.5px;font-weight:600;padding:10px 18px;border-radius:6px}
.read-more:hover{background:var(--accent-ink);color:#fff}
.read-more span{transition:transform .16s ease}
.read-more:hover span{transform:translateX(3px)}
.post-meta .post-author{color:var(--ink-soft)}

/* ============================================================
   "Most Downloaded" (PopularPosts) sidebar widget.
   Blogger's default markup prints a long snippet under every
   entry, which turned the sidebar into dozens of lines per
   post. The widget renders the custom includable below instead:
   a small thumbnail plus the title, nothing else.
   ============================================================ */
.popular-list{list-style:none;margin:0;padding:0}
.popular-list li{border-bottom:1px solid var(--line);padding:9px 0}
.popular-list li:first-child{padding-top:2px}
.popular-list li:last-child{border-bottom:none;padding-bottom:0}
.sidebar .popular-list a{display:flex;gap:12px;align-items:center;font-family:var(--font-head);
  font-size:14px;font-weight:600;line-height:1.4;color:var(--ink)}
.sidebar .popular-list a:hover{color:var(--accent)}
/* object-fit:contain (not cover): the whole thumbnail stays visible inside
   the 56px box, letterboxed on the grey ground - nothing is cropped. */
.sidebar .popular-list img{width:56px;height:56px;flex:none;object-fit:contain;border-radius:6px;
  background:#EAEEF3}

/* labels + comment link on the post page itself */
.post-labels a{display:inline-block;font-family:var(--font-head);font-size:11px;font-weight:600;
  letter-spacing:.06em;text-transform:uppercase;color:var(--accent);border:1px solid #D6E4E0;
  background:#F1F7F5;padding:4px 9px;margin:0 6px 6px 0;border-radius:4px}
.post-labels a:hover{background:var(--accent);border-color:var(--accent);color:#fff}
.comment-link{display:inline-block;margin-top:6px;font-family:var(--font-head);font-size:13px;
  font-weight:600;color:var(--accent)}
.comment-link:hover{color:var(--accent-ink)}

@media(max-width:760px){
  .card-body{padding:16px 18px 18px}
  .card-title{font-size:19.5px}
}
